{('<section id="approfondimenti"><h2>Se vuoi andare oltre</h2>'+''.join('<details><summary>'+e(a['title'])+'</summary>'+a['html']+'</details>' for a in d['deepening'])+'</section>') if d['deepening'] else ''}
