FONT='/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf'
def lines(text,size,width):
 font=ImageFont.truetype(FONT,size);out=[];line=''
 for word in text.split():
  test=(line+' '+word).strip()
  if font.getlength(test)>width and line:out.append(line);line=word
  else:line=test
 if line:out.append(line)
 return out
MAP_AUDIT=[]
def svgtext(text,x,y,size=28,color='#172b36',width=340,bold=False):
 ls=lines(text,size,width);MAP_AUDIT.append({'text':text,'lines':len(ls),'size':size,'width':width})
 return '<text x="'+str(x)+'" y="'+str(y)+'" text-anchor="middle" fill="'+color+'" font-family="DejaVu Serif, Georgia, serif" font-size="'+str(size)+'"'+(' font-weight="bold"' if bold else '')+'>'+''.join('<tspan x="'+str(x)+'" dy="'+('0' if i==0 else str(size*1.4))+'">'+e(t)+'</tspan>' for i,t in enumerate(ls))+'</text>'
def makemap(d):
 m=d['map'];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="1120" viewBox="0 0 1440 1120" role="img" aria-labelledby="title desc"><title id="title">'+e(d['title'])+'</title><desc id="desc">'+e(m['root']+'. '+' '.join(m['root']+' '+b['link']+' '+b['title']+'. '+b['body']+' '+b['title']+' '+b['relation']+' '+b['child']+'. '+b['detail'] for b in m['branches']))+'</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#a25e31"/></marker></defs><rect width="1440" height="1120" fill="#f5ead2"/><rect x="24" y="24" width="1392" height="1072" rx="9" fill="none" stroke="#a57c45" stroke-width="2"/>']
 for x in range(55,1380,44):
  for y in [52,1064]:svg.append(f'<path d="M{x} {y}h32v-16h-22v8h12" fill="none" stroke="#ad7844" stroke-width="2"/>')
 svg.append(svgtext(d['area'].upper()+' · '+d['number']+' · MAPPA CONCETTUALE',720,110,22,'#8a392b',1250))
 svg.append('<rect x="420" y="155" width="600" height="142" rx="10" fill="#0b2e47" stroke="#c99145" stroke-width="3"/>')
 svg.append(svgtext(m['root'],720,213 if len(lines(m['root'],34,540))>1 else 239,34,'#fff6df',540,True))
 for idx,b in enumerate(m['branches']):
  x=60+idx*460;cx=x+200
  svg.append(f'<path d="M720 300 V342 H{cx} V438" fill="none" stroke="#a25e31" stroke-width="3" marker-end="url(#arrow)"/>')
  svg.append(f'<rect x="{cx-200}" y="358" width="400" height="51" rx="20" fill="#f5ead2"/>')
  svg.append(svgtext(b['link'],cx,390,25,'#7d3728',390))
  svg.append(f'<rect x="{x}" y="450" width="400" height="204" rx="9" fill="#fff9eb" stroke="#8a392b" stroke-width="2"/><rect x="{x}" y="450" width="400" height="8" rx="3" fill="#8a392b"/>')
  titlelines=len(lines(b['title'],29,352));svg.append(svgtext(b['title'],cx,500,29,'#78372a',352,True));svg.append(svgtext(b['body'],cx,544+(titlelines-1)*32,24,'#172b36',350))
  svg.append(f'<path d="M{cx} 657 V789" fill="none" stroke="#a25e31" stroke-width="3" marker-end="url(#arrow)"/><rect x="{cx-197}" y="688" width="394" height="64" rx="22" fill="#f5ead2"/>')
  svg.append(svgtext(b['relation'],cx,726,24,'#7d3728',384))
  svg.append(f'<rect x="{x}" y="800" width="400" height="204" rx="9" fill="#e9d3b5" stroke="#b08a59" stroke-width="2"/>')
  n=len(lines(b['child'],28,352));svg.append(svgtext(b['child'],cx,849,28,'#0b2e47',352,True));svg.append(svgtext(b['detail'],cx,896+(n-1)*31,24,'#172b36',350))
 svg.append('</svg>');write('assets/mappe/'+d['id']+'.svg',''.join(svg))
overview={'id':'00-percorso','area':'Antologia e Cittadinanza','number':'PRIMA','title':'Racconti, miti e scelte: il percorso','map':{'root':'Racconti, miti e scelte','branches':[{'title':'Narrare','body':'01–02 · Racconto, media e funzioni del mito.','link':'imparare a','child':'Comunicare','detail':'C1 · Modelli, stereotipi e responsabilità.','relation':'apre domande sul'},{'title':'Leggere il limite','body':'03–05 · Hybris, Edipo e Antigone.','link':'permette di','child':'Prove e dissenso','detail':'C2–C3 · Giudizio, leggi e argomentazione.','relation':'si confronta con'},{'title':'Scegliere e tornare','body':'06–10 · Troia, eroi e narrazione visiva.','link':'aiuta a discutere','child':'Conflitto e identità','detail':'C4–C5 · Umanità, ospitalità, riconoscimento.','relation':'interroga'}]}}
